static class VoiceWindowNative {
 const int GwlExStyle=-20,WsExNoActivate=0x08000000,WsExToolWindow=0x00000080;
 [DllImport("user32.dll")] static extern int GetWindowLong(IntPtr window,int index);
 [DllImport("user32.dll")] static extern int SetWindowLong(IntPtr window,int index,int value);
 public static void MakeNoActivate(Window window){try{IntPtr handle=new WindowInteropHelper(window).Handle;int value=GetWindowLong(handle,GwlExStyle);SetWindowLong(handle,GwlExStyle,value|WsExNoActivate|WsExToolWindow);}catch{}}
}

sealed class VoiceHud : Window,IDisposable {
