 public event Action CancelRequested;
 public VoiceHud(ResourceDictionary resources) {
  if(resources!=null)Resources=resources;Title="BanaStudio · 语音识别";Width=480;Height=164;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;AllowsTransparency=false;Background=ColorBrush(1,255,255,255);Topmost=true;ShowInTaskbar=false;ShowActivated=false;Focusable=false;
  var shell=new Border{Background=ColorBrush(230,250,250,251),BorderBrush=ColorBrush(180,255,255,255),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(18),Padding=new Thickness(18,14,14,14)};
  var layout=new Grid();layout.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});layout.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});layout.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});
  var head=new Grid();head.ColumnDefinitions.Add(new ColumnDefinition());head.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});stateText=new TextBlock{Text="准备就绪",FontSize=15,FontWeight=FontWeights.SemiBold,Foreground=Brush("#414145")};timeText=new TextBlock{Text="00:00",FontSize=12,Foreground=Brush("#777980"),VerticalAlignment=VerticalAlignment.Center};Grid.SetColumn(timeText,1);head.Children.Add(stateText);head.Children.Add(timeText);layout.Children.Add(head);
  level=new ProgressBar{Minimum=0,Maximum=1,Height=5,Margin=new Thickness(0,10,0,0),IsHitTestVisible=false};Grid.SetRow(level,1);layout.Children.Add(level);
  var body=new Grid{Margin=new Thickness(0,10,0,0)};body.ColumnDefinitions.Add(new ColumnDefinition());body.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(92)});transcript=new TextBlock{Text="按语音快捷键开始讲话",FontSize=13,Foreground=Brush("#55565B"),TextWrapping=TextWrapping.Wrap,MaxHeight=48,VerticalAlignment=VerticalAlignment.Center};cancelButton=new Button{Content="取消",Width=80,Height=38,IsEnabled=false,VerticalAlignment=VerticalAlignment.Center};cancelButton.Click+=(s,e)=>{var handler=CancelRequested;if(handler!=null)handler();};Grid.SetColumn(cancelButton,1);body.Children.Add(transcript);body.Children.Add(cancelButton);Grid.SetRow(body,2);layout.Children.Add(body);shell.Child=layout;Content=shell;
  SourceInitialized+=(s,e)=>{WindowBackdrop.Enable(this);OverlayNative.SetWindowDisplayAffinity(new WindowInteropHelper(this).Handle,0x11);VoiceWindowNative.MakeNoActivate(this);};
  Loaded+=(s,e)=>{Rect work=SystemParameters.WorkArea;Left=work.Left+(work.Width-Width)/2;Top=work.Bottom-Height-24;};
  Closing+=(s,e)=>{if(!disposing){e.Cancel=true;Hide();}};
 }
 static SolidColorBrush ColorBrush(byte a,byte r,byte g,byte b){return new SolidColorBrush(Color.FromArgb(a,r,g,b));}
 static Brush Brush(string value){return new SolidColorBrush((Color)ColorConverter.ConvertFromString(value));}
 public void Update(VoiceState state,string text,double volume,TimeSpan elapsed) {
  if(!Dispatcher.CheckAccess()){Dispatcher.BeginInvoke(new Action(()=>Update(state,text,volume,elapsed)));return;}
  string label;switch(state){case VoiceState.Starting:label="正在连接语音服务…";break;case VoiceState.Listening:label="正在听…";break;case VoiceState.Finalizing:label="正在完成识别…";break;case VoiceState.Delivering:label="正在输入…";break;case VoiceState.Error:label="识别失败";break;case VoiceState.Cancelled:label="已取消";break;default:label="准备就绪";break;}
  stateText.Text=label;stateText.Foreground=state==VoiceState.Error?Brush("#B3433D"):Brush("#414145");timeText.Text=elapsed.TotalHours>=1?elapsed.ToString(@"hh\:mm\:ss"):elapsed.ToString(@"mm\:ss");level.Value=Math.Max(0,Math.Min(1,volume));if(text!=null)transcript.Text=string.IsNullOrWhiteSpace(text)?(state==VoiceState.Finalizing?"正在等待最终文字…":"请开始讲话"):text;cancelButton.IsEnabled=state==VoiceState.Starting||state==VoiceState.Listening||state==VoiceState.Finalizing;
 }
 public void SetError(string message){Update(VoiceState.Error,message,0,TimeSpan.Zero);}
 public void Dispose(){if(disposing)return;disposing=true;Close();}
}

static class VoiceLibraryPersistence {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4*1024*1024};
 public static void SaveHistory(IEnumerable<VoiceHistoryItem> items) {
  string path=Path.Combine(VoiceData.Root,"history.json");Directory.CreateDirectory(Path.GetDirectoryName(path));string temporary=path+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllText(temporary,Json.Serialize(items.ToList()),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temporary,path,path+".bak",true);else File.Move(temporary,path);
 }
}

