 static Brush Brush(string value){return new SolidColorBrush((Color)ColorConverter.ConvertFromString(value));}
 static List<string> ParseAliases(string text){return (text??"").Split(new[]{'|',';'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).Where(x=>x.Length>0).Distinct(StringComparer.Ordinal).Take(20).ToList();}
 Border Card(UIElement child){return new Border{Child=child,Background=Brush("#FFFFFFFF"),BorderBrush=Brush("#E4E4E8"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Padding=new Thickness(10),Margin=new Thickness(0,0,0,8)};}
 void SetStatus(string value){status.Text=value;}
 void SaveTerms(string message){VoiceData.SaveTerms(terms);RefreshTerms();var handler=TermsChanged;if(handler!=null)handler(terms);SetStatus(message);}
 void SaveHistory(string message){VoiceLibraryPersistence.SaveHistory(history);RefreshHistory();var handler=HistoryChanged;if(handler!=null)handler(history);SetStatus(message);}
 public void MergeImported(IEnumerable<VoiceTerm> incoming){terms=VoiceData.Merge(terms,incoming??new VoiceTerm[0]);SaveTerms("词库已合并导入");}
 public void ReplaceHistory(IEnumerable<VoiceHistoryItem> values){history=(values??new VoiceHistoryItem[0]).ToList();RefreshHistory();}
 void AddTerm(){string word=(newWord.Text??"").Trim();if(word.Length==0){SetStatus("请输入正确词语");return;}if(word.Length>100){SetStatus("词语长度不能超过 100 个字符");return;}if(terms.Any(x=>string.Equals(x.word,word,StringComparison.Ordinal))){SetStatus("词库中已有这个词");return;}terms.Add(VoiceData.NewTerm(word,ParseAliases(newAliases.Text),"manual"));newWord.Clear();newAliases.Clear();SaveTerms("已添加专有词");}
 void RefreshTerms(){if(termRows==null)return;termRows.Children.Clear();string query=(search.Text??"").Trim();var shown=terms.Where(x=>query.Length==0||(x.word??"").IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0||(x.aliases??new List<string>()).Any(a=>(a??"").IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0)).OrderBy(x=>x.word,StringComparer.CurrentCulture).Take(500).ToList();termSummary.Text="搜索词语或别名 · 列：正确词语 / 常见误识别（可选） · "+terms.Count(x=>x.enabled)+" 个启用 · "+terms.Count+" 个词"+(shown.Count<terms.Count?" · 当前显示前 "+shown.Count+" 个":"");foreach(var term in shown)termRows.Children.Add(TermRow(term));}
 UIElement TermRow(VoiceTerm term){var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(44)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(170)});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(72)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(72)});var enabled=new CheckBox{IsChecked=term.enabled,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,ToolTip="启用"};var word=new TextBox{Text=term.word,Height=34,Margin=new Thickness(4,0,6,0)};var aliases=new TextBox{Text=string.Join("|",term.aliases??new List<string>()),Height=34,Margin=new Thickness(0,0,6,0),ToolTip="常见误识别，用 | 分隔"};var save=new Button{Content="保存",Margin=new Thickness(2,0,2,0)};var remove=new Button{Content="删除",Margin=new Thickness(2,0,0,0)};enabled.Checked+=(s,e)=>{term.enabled=true;SaveTerms("已启用 "+term.word);};enabled.Unchecked+=(s,e)=>{term.enabled=false;SaveTerms("已停用 "+term.word);};save.Click+=(s,e)=>{string value=(word.Text??"").Trim();if(value.Length==0||value.Length>100){SetStatus("词语不能为空且不能超过 100 个字符");return;}if(terms.Any(x=>!ReferenceEquals(x,term)&&string.Equals(x.word,value,StringComparison.Ordinal))){SetStatus("词库中已有这个词");return;}term.word=value;term.aliases=ParseAliases(aliases.Text);term.updatedAt=DateTime.UtcNow.ToString("o");SaveTerms("已保存词语");};remove.Click+=(s,e)=>{terms.Remove(term);SaveTerms("已删除词语");};grid.Children.Add(enabled);Grid.SetColumn(word,1);grid.Children.Add(word);Grid.SetColumn(aliases,2);grid.Children.Add(aliases);Grid.SetColumn(save,3);grid.Children.Add(save);Grid.SetColumn(remove,4);grid.Children.Add(remove);return Card(grid);}
 void RefreshHistory(){if(historyRows==null)return;historyRows.Children.Clear();historySummary.Text=history.Count+" 条本地转写";foreach(var item in history.OrderByDescending(x=>x.createdAt).Take(500))historyRows.Children.Add(HistoryRow(item));}
 UIElement HistoryRow(VoiceHistoryItem item){var layout=new Grid();layout.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});layout.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var meta=new TextBlock{Text=HistoryTime(item.createdAt)+" · "+(item.status=="final"?"已完成":"未完成草稿"),FontSize=11,Foreground=Brush("#777980")};layout.Children.Add(meta);var row=new Grid{Margin=new Thickness(0,7,0,0)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(66)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(108)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(66)});var text=new TextBlock{Text=item.text??"",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,8,4)};var copy=new Button{Content="复制",Margin=new Thickness(2,0,2,0)};var correct=new Button{Content="纠错并记住",Margin=new Thickness(2,0,2,0)};var remove=new Button{Content="删除",Margin=new Thickness(2,0,0,0)};copy.Click+=(s,e)=>Copy(item.text);correct.Click+=(s,e)=>BeginCorrection(item);remove.Click+=(s,e)=>{history.Remove(item);SaveHistory("已删除历史");};row.Children.Add(text);Grid.SetColumn(copy,1);row.Children.Add(copy);Grid.SetColumn(correct,2);row.Children.Add(correct);Grid.SetColumn(remove,3);row.Children.Add(remove);Grid.SetRow(row,1);layout.Children.Add(row);return Card(layout);}
 static string HistoryTime(string value){DateTime parsed;return DateTime.TryParse(value,out parsed)?parsed.ToLocalTime().ToString("yyyy-MM-dd HH:mm"):"时间未知";}
 void Copy(string value){if(string.IsNullOrEmpty(value))return;var handler=CopyRequested;if(handler!=null){handler(value);SetStatus("已请求复制");return;}try{Clipboard.SetText(value);SetStatus("已复制到剪贴板");}catch{SetStatus("剪贴板正被占用，请稍后重试");}}
 void ClearHistory(){history.Clear();VoiceData.ClearHistory();RefreshHistory();var handler=HistoryChanged;if(handler!=null)handler(history);SetStatus("历史已清空");}
 void BeginCorrection(VoiceHistoryItem item){correctionItem=item;wrongWord.Clear();correctWord.Clear();correctionPanel.Visibility=Visibility.Visible;wrongWord.Focus();SetStatus("输入错误词和正确词，保存后会加入词库");}
 void RememberCorrection(){if(correctionItem==null)return;string wrong=(wrongWord.Text??"").Trim(),correct=(correctWord.Text??"").Trim();if(wrong.Length==0||correct.Length==0){SetStatus("错误词和正确词都不能为空");return;}if(correct.Length>100){SetStatus("正确词不能超过 100 个字符");return;}var term=terms.FirstOrDefault(x=>string.Equals(x.word,correct,StringComparison.Ordinal));if(term==null){term=VoiceData.NewTerm(correct,new List<string>{wrong},"correction");terms.Add(term);}else{term.aliases=(term.aliases??new List<string>()).Concat(new[]{wrong}).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.Ordinal).Take(20).ToList();term.enabled=true;term.updatedAt=DateTime.UtcNow.ToString("o");}if(!string.IsNullOrEmpty(correctionItem.text))correctionItem.text=correctionItem.text.Replace(wrong,correct);VoiceData.SaveTerms(terms);VoiceLibraryPersistence.SaveHistory(history);RefreshTerms();RefreshHistory();correctionPanel.Visibility=Visibility.Collapsed;var termsHandler=TermsChanged;if(termsHandler!=null)termsHandler(terms);var historyHandler=HistoryChanged;if(historyHandler!=null)historyHandler(history);var correctionHandler=CorrectionRemembered;if(correctionHandler!=null)correctionHandler(wrong,correct);SetStatus("已纠正，并把正确词加入热词词库");}
}
